import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { deleteRequest, getRequests } from '../services/requestService';
import { useAuth } from '../context/AuthContext';
import { toast } from 'react-toastify';
import { FiFileText, FiCalendar, FiUser, FiCheckCircle, FiClock, FiXCircle, FiAlertCircle, FiTrash2, FiEye, FiFilter, FiSearch } from 'react-icons/fi';

const RequestList = () => {
  const { user } = useAuth();
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [deletingId, setDeletingId] = useState(null);

  useEffect(() => {
    loadRequests();
  }, []);

  const loadRequests = async () => {
    try {
      const data = await getRequests();
      // "Mes demandes" must only contain requests created by current user.
      const mine = data.filter((req) => Number(req.createdBy) === Number(user?.id));
      setRequests(mine);
    } catch (error) {
      toast.error('Erreur lors du chargement des demandes');
      setRequests([]);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    const confirmed = window.confirm('Voulez-vous vraiment supprimer cette demande ?');
    if (!confirmed) return;

    try {
      setDeletingId(id);
      await deleteRequest(id);
      setRequests((prev) => prev.filter((req) => req.id !== id));
      toast.success('Demande supprimee avec succes');
    } catch (error) {
      toast.error(error?.response?.data?.message || 'Erreur lors de la suppression');
    } finally {
      setDeletingId(null);
    }
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Mes demandes</h1>
        <Link to="/requests/new" className="btn btn-primary">+ Nouvelle demande</Link>
      </div>
      <div className="table-container">
        {loading && (
          <div className="text-center py-8">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
            <p className="text-gray-600 mt-4">Chargement des demandes...</p>
          </div>
        )}

        {!loading && requests.length === 0 && (
          <div className="text-center py-12">
            <p className="text-gray-500 text-xl">📝 Aucune demande trouvée</p>
            <p className="text-gray-400 text-sm mt-2">Vos demandes apparaîtront ici une fois créées</p>
          </div>
        )}

        {!loading && requests.length > 0 && (
          <>
            <div className="table-header">
              <div>
                <h2 className="table-title">Mes demandes</h2>
                <p className="table-subtitle">Gestion et suivi de toutes vos demandes</p>
              </div>
              <div className="table-stats">
                <div className="table-stats-item">
                  <span className="table-stats-icon">📋</span>
                  <span>{requests.length} demande(s)</span>
                </div>
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="professional-table">
                <thead>
                  <tr>
                    <th>Référence</th>
                    <th>Type de processus</th>
                    <th>Créée par</th>
                    <th>Assignée à</th>
                    <th>Statut</th>
                    <th>Date de création</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {requests.map((req) => {
                    const assignedToMe = req.assignedTo === user?.id || req.assignee?.id === user?.id;
                    return (
                      <tr key={req.id}>
                        <td className="font-mono font-semibold text-blue-700">{req.reference}</td>
                        <td className="font-medium text-gray-900">{req.workflowType}</td>
                        <td className="text-gray-700">{req.creator?.fullName || 'N/A'}</td>
                        <td className="text-gray-700">
                          {req.assignee?.fullName || req.assignedTo || 'Non assigné'}
                          {assignedToMe && <span className="ml-2 text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded-full">À moi</span>}
                        </td>
                        <td className="status-cell">
                          <span className={`status-badge status-badge-${req.status}`}>
                            {req.status}
                          </span>
                        </td>
                        <td className="text-gray-600">
                          {new Date(req.createdAt).toLocaleDateString('fr-FR', {
                            day: '2-digit',
                            month: '2-digit',
                            year: 'numeric'
                          })}
                        </td>
                        <td className="action-cell">
                          <Link
                            to={`/requests/${req.id}`}
                            className="action-btn action-btn-primary"
                          >
                            👁️ Voir
                          </Link>
                          <button
                            type="button"
                            className="action-btn action-btn-danger"
                            onClick={() => handleDelete(req.id)}
                            disabled={deletingId === req.id}
                          >
                            {deletingId === req.id ? '⏳ Suppression...' : '🗑️ Supprimer'}
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default RequestList;
